#!/usr/bin/env python3
"""Package byte-identical external archives using proofs generated by the target tag."""

import argparse
import json
from pathlib import Path
import re
import subprocess
import sys
import tempfile

from seed_release_host_packages import immutable_release


def verify_archive(verifier, path, pin, asset):
    digest = asset.get("digest", "")
    if (asset.get("state") != "uploaded" or not re.fullmatch("sha256:[0-9a-f]{64}", digest)
            or not 0 < asset["size"] < 2 << 30 or path.stat().st_size != asset["size"]):
        raise ValueError(f"invalid release archive metadata for {path.name}")
    result = subprocess.run([str(verifier), "external-image-proof", "--archive", str(path),
                             "--reference", pin["reference"]], capture_output=True, timeout=600)
    if result.returncode:
        raise ValueError(f"target native verifier rejected {path.name}")
    proof = json.loads(result.stdout)
    if (proof["archive_sha256"] != digest[7:] or proof["archive_bytes"] != asset["size"]
            or any(proof[key] != pin[key] for key in ("reference", "index_digest", "manifest_digest", "config_digest"))):
        raise ValueError(f"target proof differs from published bytes or target lock for {path.name}")
    return proof


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", required=True, type=Path)
    parser.add_argument("--source-sha", required=True)
    parser.add_argument("--repository", required=True)
    parser.add_argument("--release", required=True)
    parser.add_argument("--seed-release", required=True)
    parser.add_argument("--output-dir", required=True, type=Path)
    args = parser.parse_args()
    source = args.source.resolve(strict=True)
    sys.path.insert(0, str(source / "Tests/tools"))
    import build_node_external_assets as target

    if (not target.bootstrap.REPOSITORY.fullmatch(args.repository)
            or not all(target.bootstrap.RELEASE.fullmatch(r) for r in (args.release, args.seed_release))
            or not target.bootstrap.packaging_identity(args.release, args.source_sha)
            or target.bootstrap.git(source, "rev-parse", "HEAD") != args.source_sha):
        raise ValueError("invalid release packaging identity")
    meta = immutable_release(args.repository, args.seed_release)
    assets = {asset["name"]: asset for asset in meta["assets"]}
    output = args.output_dir.absolute()
    if output.exists():
        raise ValueError("release packaging output already exists")
    with tempfile.TemporaryDirectory(dir=output.parent) as tmp:
        root = Path(tmp)
        snapshot, verifier, stage = root / "source", root / "node-manager", root / "external"
        target.bootstrap.source_snapshot(source, snapshot, args.release, args.source_sha, args.repository)
        lock = json.loads((snapshot / target.pins.LOCK).read_bytes(), object_pairs_hook=target.pins.unique_object)
        target.pins.validate_pin_sources(snapshot, lock)
        pins = sorted((pin for c in lock["components"] for pin in c["images"]), key=lambda p: p["reference"])
        names = [target.asset_name(pin["reference"]) for pin in pins]
        if len(set(names)) != len(names) or not set(names).issubset(assets):
            raise ValueError("seed release lacks distinct required archive names")
        target.bootstrap.build_manager(snapshot, verifier, "go")
        stage.mkdir(mode=0o700)
        proofs = []
        for name, pin in zip(names, pins):
            subprocess.run(["gh", "release", "download", args.seed_release, "--repo", args.repository,
                            "--pattern", name, "--output", str(stage / name)], check=True)
            proofs.append(verify_archive(verifier, stage / name, pin, assets[name]))
        inventory = dict(version=1, repository=args.repository, release=args.release, source_sha=args.source_sha,
                         platform="linux-amd64", images=proofs)
        (stage / target.INVENTORY).write_text(json.dumps(inventory, sort_keys=True, separators=(",", ":")) + "\n")
        stage.rename(output)
        print(f"Verified {len(proofs)} retained archives with the target release's native verifier")


if __name__ == "__main__":
    main()
